CREATE TEMPORARY VIEW traffic_${grass_region_without_quote} AS
select model_id
    ,is_win_day
    ,control_imp_cnt
    ,control_gmv
    ,local_date
    from srdi_mart.dws_sr_data_warehouse_tc_pb_reward_model_exp_level_1d
where grass_region = ${grass_region}
and local_date between date_sub(${local_date},43) and ${local_date}
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW traffic_by_d0_${grass_region_without_quote} AS
SELECT t1.local_date as d0
    ,t2.*
from (
    select local_date
    from traffic_${grass_region_without_quote}
    where local_date between date_sub(${local_date},36) and date_sub(${local_date},7)
    group by 1
 )t1
inner join traffic_${grass_region_without_quote} t2
on t2.local_date between date_sub(t1.local_date,7) and date_sub(t1.local_date,-7)
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW new_winner_${grass_region_without_quote} AS
select d0
     ,model_id
from (
      SELECT d0
           ,model_id
           , MAX(CASE WHEN local_date = d0 AND is_win_day = 1 THEN 1 ELSE 0 END) is_winner_d0
           , SUM(CASE WHEN local_date < d0 AND is_win_day = 1 THEN 1 ELSE 0 END) before_winday_cnt
           , SUM(CASE WHEN local_date > d0 AND is_win_day = 1 THEN 1 ELSE 0 END) after_winday_cnt
      FROM traffic_by_d0_${grass_region_without_quote}
      GROUP BY 1,2
)x
where is_winner_d0 = 1 and before_winday_cnt<=1 and after_winday_cnt>=6
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW daily_uplift_${grass_region_without_quote} AS
SELECT d0
     ,case when before_imp_cnt > 0 and 1.0000*after_imp_cnt/before_imp_cnt-1 > 0 then 1.0000*after_imp_cnt/before_imp_cnt-1
         when before_imp_cnt <= 0 and after_imp_cnt >0 then 1.0
     else 0.02 end as imp_cnt_control_uplift_pct
     ,case when before_gmv > 0 then GREATEST(after_gmv/before_gmv-1,0)
         when before_gmv<=0 and after_gmv > 0 then 1.0
     else 0 end as gmv_control_uplift_pct
from (
    SELECT a.d0
       , SUM(CASE WHEN local_date < a.d0 THEN control_imp_cnt else 0 END) before_imp_cnt
       , SUM(CASE WHEN local_date < a.d0 THEN control_gmv else 0 END)     before_gmv
       , SUM(CASE WHEN local_date > a.d0 THEN control_imp_cnt else 0 END) after_imp_cnt
       , SUM(CASE WHEN local_date > a.d0 THEN control_gmv else 0 END)     after_gmv
    FROM traffic_by_d0_${grass_region_without_quote} a
    INNER JOIN new_winner_${grass_region_without_quote} b
    ON a.d0 = b.d0
    AND a.model_id = b.model_id
    group by 1
)x
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_tc_pb_reward_control_uplift_15d
partition (grass_region = ${grass_region},local_date = ${local_date})
select sum(imp_cnt_control_uplift_pct)/30 as imp_cnt_control_uplift_pct
    ,sum(gmv_control_uplift_pct)/30 as gmv_control_uplift_pct

    ,collect_list(concat(d0,'_',cast(imp_cnt_control_uplift_pct as string))) as imp_cnt_control_uplift_pct_list
    ,collect_list(concat(d0,'_',cast(gmv_control_uplift_pct as string))) as gmv_control_uplift_pct_list
from daily_uplift_${grass_region_without_quote}
;
